import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DStH8c-G.js";var i=JSON.parse(`{"title":"Class: GenerationPool","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: GenerationPool"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/GenerationPool"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/GenerationPool"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/chunkgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/chunkgen/classes/GenerationPool.md","filePath":"api/@jsprismarine/chunkgen/classes/GenerationPool.md","lastUpdated":1794433523000}`),a={name:`api/@jsprismarine/chunkgen/classes/GenerationPool.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/chunkgen</a> / GenerationPool</p><h1 id="class-generationpool" tabindex="-1">Class: GenerationPool <a class="header-anchor" href="#class-generationpool" aria-label="Permalink to “Class: GenerationPool”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L587" target="_blank" rel="noreferrer">GenerationPool.ts:587</a></p><p>Runs status bodies in worker threads.</p><p>The main thread keeps the holders, the scheduler, the feature patch merge and the translation to Bedrock runtime ids. A worker only ever sees one chunk&#39;s worth of work and hands back flat typed arrays.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new GenerationPool</strong>(<code>options</code>, <code>runner?</code>): <code>GenerationPool</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L660" target="_blank" rel="noreferrer">GenerationPool.ts:660</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#generationpooloptions"><code>GenerationPoolOptions</code></a></p><p>The pipeline module, the worker entry, the worker count and the setup.</p><h5 id="runner" tabindex="-1">runner? <a class="header-anchor" href="#runner" aria-label="Permalink to “runner?”">​</a></h5><p><a href="./../#taskrunnerfactory"><code>TaskRunnerFactory</code></a> = <code>piscinaRunner</code></p><p>How to build the task runner. Defaults to piscina; a test passes a double.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>GenerationPool</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="options-1" tabindex="-1">options <a class="header-anchor" href="#options-1" aria-label="Permalink to “options”">​</a></h3><blockquote><p><code>readonly</code> <strong>options</strong>: <a href="./../#generationpooloptions"><code>GenerationPoolOptions</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L661" target="_blank" rel="noreferrer">GenerationPool.ts:661</a></p><p>The pipeline module, the worker entry, the worker count and the setup.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="inflight" tabindex="-1">inFlight <a class="header-anchor" href="#inflight" aria-label="Permalink to “inFlight”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>inFlight</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L712" target="_blank" rel="noreferrer">GenerationPool.ts:712</a></p><p>How many tasks the workers are holding right now.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><hr><h3 id="queued" tabindex="-1">queued <a class="header-anchor" href="#queued" aria-label="Permalink to “queued”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>queued</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L717" target="_blank" rel="noreferrer">GenerationPool.ts:717</a></p><p>How many tasks are waiting for a worker, across every band.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><hr><h3 id="workers" tabindex="-1">workers <a class="header-anchor" href="#workers" aria-label="Permalink to “workers”">​</a></h3><h4 id="get-signature-2" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-2" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>workers</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L707" target="_blank" rel="noreferrer">GenerationPool.ts:707</a></p><p>How many workers are up. Zero once the pool has been shut down.</p><h5 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="cancel" tabindex="-1">cancel() <a class="header-anchor" href="#cancel" aria-label="Permalink to “cancel()”">​</a></h3><blockquote><p><strong>cancel</strong>(<code>wanted</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L765" target="_blank" rel="noreferrer">GenerationPool.ts:765</a></p><p>Drops every waiting task a predicate picks out, and reports how many went.</p><p>Only the backlog: a task a worker already has cannot be taken back without terminating the worker, which costs more than letting the chunk finish. That is the right trade for what this is for - a player turning around leaves an <code>idle</code> rim nobody will ever look at, and the few already running are the cheapest part of it.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="wanted" tabindex="-1">wanted <a class="header-anchor" href="#wanted" aria-label="Permalink to “wanted”">​</a></h5><p>(<code>task</code>) =&gt; <code>boolean</code></p><p>Answers true for a task that should still be built.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>How many tasks were dropped.</p><hr><h3 id="destroy" tabindex="-1">destroy() <a class="header-anchor" href="#destroy" aria-label="Permalink to “destroy()”">​</a></h3><blockquote><p><strong>destroy</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L825" target="_blank" rel="noreferrer">GenerationPool.ts:825</a></p><p>Stops every worker, interrupting whatever they are doing.</p><p>Worker threads do not receive signals, so terminating them is the only way to stop one mid-chunk. Measured at 2 to 24 ms for a worker in a tight loop.</p><p>Everything still in the backlog is refused first, so a shutdown does not leave a caller waiting on a turn that is never going to come.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="promote" tabindex="-1">promote() <a class="header-anchor" href="#promote" aria-label="Permalink to “promote()”">​</a></h3><blockquote><p><strong>promote</strong>(<code>wanted</code>, <code>to</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L797" target="_blank" rel="noreferrer">GenerationPool.ts:797</a></p><p>Moves waiting tasks up into a band, and reports how many moved.</p><p>What a chunk that has become more urgent needs. A rim chunk asked for as <code>idle</code> is the same chunk a player is standing on a moment later, and without this it would keep the turn it was given when nobody wanted it. A task already in the band or above it is left where it is, so this only ever moves work forward.</p><p>Order inside the destination band is arrival order, and a promoted task arrives now: it goes behind everything already waiting there, not in front of it.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="wanted-1" tabindex="-1">wanted <a class="header-anchor" href="#wanted-1" aria-label="Permalink to “wanted”">​</a></h5><p>(<code>task</code>) =&gt; <code>boolean</code></p><p>Answers true for a task that should move.</p><h5 id="to" tabindex="-1">to <a class="header-anchor" href="#to" aria-label="Permalink to “to”">​</a></h5><p><code>&quot;immediate&quot;</code> | <code>&quot;soon&quot;</code> | <code>&quot;idle&quot;</code></p><p>The band to move it into.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>How many tasks moved.</p><hr><h3 id="resetstats" tabindex="-1">resetStats() <a class="header-anchor" href="#resetstats" aria-label="Permalink to “resetStats()”">​</a></h3><blockquote><p><strong>resetStats</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L679" target="_blank" rel="noreferrer">GenerationPool.ts:679</a></p><p>Forgets the recorded task stats.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="run" tabindex="-1">run() <a class="header-anchor" href="#run" aria-label="Permalink to “run()”">​</a></h3><blockquote><p><strong>run</strong>(<code>task</code>, <code>priority?</code>): <code>Promise</code>&lt;<a href="./../#generationresult"><code>GenerationResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L741" target="_blank" rel="noreferrer">GenerationPool.ts:741</a></p><p>Runs one status body in whichever worker is free.</p><p>A task above the in-flight limit waits here rather than downstream, so a request that arrives while the queue is long is still served in <a href="./../#generationpriority">GenerationPriority</a> order instead of behind everything that was asked for first.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="task" tabindex="-1">task <a class="header-anchor" href="#task" aria-label="Permalink to “task”">​</a></h5><p><a href="./../#generationtask"><code>GenerationTask</code></a></p><p>The status, the position and whatever else the body reads.</p><h5 id="priority" tabindex="-1">priority? <a class="header-anchor" href="#priority" aria-label="Permalink to “priority?”">​</a></h5><p><code>&quot;immediate&quot;</code> | <code>&quot;soon&quot;</code> | <code>&quot;idle&quot;</code> = <code>&#39;immediate&#39;</code></p><p>Which band the task waits in. Defaults to <code>immediate</code>, so a caller that has not thought about it gets the behavior it would have had with no queue at all.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../#generationresult"><code>GenerationResult</code></a>&gt;</p><p>What the body produced, with its buffers now owned by this thread.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>GenerationPoolClosedError when the pool has been shut down, whether that was before the task was asked for or while it was waiting.</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>GenerationCanceledError when <a href="#cancel">GenerationPool.cancel</a> dropped it.</p><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to “Throws”">​</a></h4><p>Whatever the body threw, so a worker that fails rejects the request rather than leaving it outstanding forever.</p><hr><h3 id="setbackgroundlimit" tabindex="-1">setBackgroundLimit() <a class="header-anchor" href="#setbackgroundlimit" aria-label="Permalink to “setBackgroundLimit()”">​</a></h3><blockquote><p><strong>setBackgroundLimit</strong>(<code>limit</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L692" target="_blank" rel="noreferrer">GenerationPool.ts:692</a></p><p>Limits how many <code>soon</code> and <code>idle</code> tasks may be with workers at once. <code>immediate</code> tasks never count against it and are never held back by it, so a chunk a player stands on is not slowed.</p><p>Raising the limit starts waiting tasks at once. Lowering it does not interrupt a task a worker has: the running count falls as they finish.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="limit" tabindex="-1">limit <a class="header-anchor" href="#limit" aria-label="Permalink to “limit”">​</a></h5><p><code>number</code> | <code>undefined</code></p><p>The most background tasks at once, or undefined for no limit.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="statssnapshot" tabindex="-1">statsSnapshot() <a class="header-anchor" href="#statssnapshot" aria-label="Permalink to “statsSnapshot()”">​</a></h3><blockquote><p><strong>statsSnapshot</strong>(): <a href="./../#generationstatssnapshot"><code>GenerationStatsSnapshot</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L674" target="_blank" rel="noreferrer">GenerationPool.ts:674</a></p><p>What the pool has recorded about the tasks it ran, by status and priority band.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#generationstatssnapshot"><code>GenerationStatsSnapshot</code></a></p><p>A copy, so a caller can take two and subtract.</p><hr><h3 id="unavailable" tabindex="-1">unavailable() <a class="header-anchor" href="#unavailable" aria-label="Permalink to “unavailable()”">​</a></h3><blockquote><p><code>static</code> <strong>unavailable</strong>(<code>options</code>): <code>string</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/16f3acadcdd217fea44c52f4222b795f8c81dca8/packages/chunkgen/src/GenerationPool.ts#L622" target="_blank" rel="noreferrer">GenerationPool.ts:622</a></p><p>Why this process cannot run workers, or undefined when it can.</p><p>A worker thread is a second module loader rather than a copy of this one. The Node single executable packages its worker and pipelines as assets; other hosts need those modules available through Node&#39;s resolution. Asking before building lets a caller log one line and do the work on its own thread instead of starting workers that cannot import modules.</p><p>This does not promise the pipeline imports cleanly once a worker has it. That depends on the loader the host was started with, which only the import itself can settle, so a caller still needs a fallback for the first task.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-2" tabindex="-1">options <a class="header-anchor" href="#options-2" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#generationpooloptions"><code>GenerationPoolOptions</code></a></p><p>The options GenerationPool would be built with.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code> | <code>undefined</code></p><p>A sentence naming what is missing, or undefined when nothing is.</p>`,149)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};